// @matrix 128x128
// @knobs Glitch=0..1, Speed=0.394..3.365, Freq=10..120, Quantize=0.143..2.382
// Patternflow layer-stack composition — flattened by Pattern Lab.
// Layers (bottom → top):
//   1. Ocular Vortex (code, normal, 100%)
//   2. Nose (pixel, normal, 100%)
const __PW = 128, __PH = 64;
const __W = 128, __H = 128;
const __OX = (__W - __PW) >> 1, __OY = (__H - __PH) >> 1;
const __stack = [];

function __b64(s, n) {
  const A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out = new Uint8ClampedArray(n);
  let o = 0, buf = 0, bits = 0;
  for (let i = 0; i < s.length && o < n; i++) {
    const v = A.indexOf(s[i]);
    if (v < 0) continue;
    buf = (buf << 6) | v; bits += 6;
    if (bits >= 8) { bits -= 8; out[o++] = (buf >> bits) & 255; }
  }
  return out;
}

function __mkDisplay(L) {
  return {
    width: __W, height: __H,
    setPixel(x, y, r, g, b) {
      const xi = x | 0, yi = y | 0;
      if (xi < 0 || xi >= __W || yi < 0 || yi >= __H) return;
      const i = (yi * __W + xi) * 4, B = L.buf;
      if (Array.isArray(r)) { B[i] = r[0] || 0; B[i + 1] = r[1] || 0; B[i + 2] = r[2] || 0; }
      else { B[i] = r; B[i + 1] = g || 0; B[i + 2] = b || 0; }
      B[i + 3] = 255;
    },
    setValue(x, y, v) {
      const xi = x | 0, yi = y | 0;
      if (xi < 0 || xi >= __W || yi < 0 || yi >= __H) return;
      v = Number.isFinite(v) ? (v < 0 ? 0 : v > 1 ? 1 : v) : 0;
      const i = (yi * __W + xi) * 4, B = L.buf, T = L.lut;
      if (T) {
        const li = Math.round(v * 255) * 4;
        B[i] = T[li]; B[i + 1] = T[li + 1]; B[i + 2] = T[li + 2]; B[i + 3] = T[li + 3];
      } else {
        const byte = Math.round(v * 255);
        B[i] = byte; B[i + 1] = byte; B[i + 2] = byte; B[i + 3] = 255;
      }
    },
  };
}

// ── code layer: Ocular Vortex ──
(function () {
  // Shadow the wrapper's own exports: a layer that defines no setup/update
  // must yield undefined here, not capture the OUTER setup (infinite loop).
  var setup, update, draw;
// Pattern: Almond Ocular Vortex (Pixel Eye Remix)


function getComponent(h, s, v, offset) {
    let k = ((offset + h * 6.0) % 6.0 + 6.0) % 6.0;
    let c = Math.max(0.0, Math.min(k, 4.0 - k, 1.0));
    return Math.floor(255.0 * v * (1.0 - s * c));
}

function setup(params) {
    // Knob 1: Iris Hue & Spectrum (0.0 to 1.0)
    // Knob 2: Vortex & Rotation Speed (0.1 to 10.0)
    // Knob 3: Eye Distance & Fold Mode (0.0 to 4.9)
    // Knob 4: Iris Size & Vortex Twist Depth (0.0 to 1.0)
    params.k1 = 0.8;
    params.k2 = 1.5;
    params.k3 = 2.0;
    params.k4 = 0.5;
    params.timeAcc = 0.0;
}

function update(dt, input, params) {
    // Controls: Knob 1: Iris Hue | Knob 2: Vortex Speed | Knob 3: Eye Distance & Folds | Knob 4: Iris Size & Twist
    if (input && input.knobValues) {
        params.k1 = input.knobValues[0];
        params.k2 = input.knobValues[1];
        params.k3 = input.knobValues[2];
        params.k4 = input.knobValues[3];
    }
    params.timeAcc += dt * params.k2;
}

function draw(display, params, time) {
    let w = display.width;
    let h = display.height;
    let t = params.timeAcc;

    let cy = h * 0.5;

    let mode = Math.floor(Math.max(0.0, Math.min(4.0, params.k3)));
    let folds = 2 + mode * 2;

    // Eye spacing relative to display width
    let eyeSpacing = w * (0.20 + mode * 0.02);
    let cxLeft = w * 0.5 - eyeSpacing;
    let cxRight = w * 0.5 + eyeSpacing;

    // Almond eye dimensions scaled to screen size
    let rx = w * 0.18;
    let ry = h * 0.34;

    let irisR = h * (0.16 + params.k4 * 0.10);
    let pupilR = irisR * 0.48;

    let sectorAngle = (Math.PI * 2.0) / folds;
    let twistDepth = params.k4 * 0.18;
    let baseHue = params.k1;

    for (let y = 0; y < h; y++) {
        let dy = y - cy;
        for (let x = 0; x < w; x++) {
            let isRightEye = (x >= w * 0.5);
            let cx = isRightEye ? cxRight : cxLeft;

            let dx = x - cx;
            let nx = dx / rx;
            let absNx = Math.abs(nx);

            let r = 0, g = 0, b = 0;

            if (absNx < 1.0) {
                // Parabolic almond outline height
                let maxH = ry * (1.0 - nx * nx);
                let absDy = Math.abs(dy);
                let eyeDist = maxH > 0.05 ? absDy / maxH : 2.0;

                if (eyeDist <= 1.0) {
                    if (eyeDist >= 0.78) {
                        // Almond Eyelid Outline Frame
                        let outlineHue = (baseHue + 0.5) % 1.0;
                        r = getComponent(outlineHue, 0.7, 0.9, 5);
                        g = getComponent(outlineHue, 0.7, 0.9, 3);
                        b = getComponent(outlineHue, 0.7, 0.9, 1);
                    } else {
                        // Inside Eye Contour
                        let distToPupil = Math.sqrt(dx * dx + dy * dy);

                        if (distToPupil <= irisR) {
                            // Iris / Pupil Field
                            let mirrorDx = isRightEye ? -dx : dx;

                            // Crescent glint reflection inside pupil
                            let gx = cx - irisR * 0.12;
                            let gy = cy + irisR * 0.12;
                            let gDist = Math.sqrt((x - gx) * (x - gx) + (y - gy) * (y - gy));
                            let isGlint = (gDist < pupilR * 0.55) && !(x < gx && y > gy);

                            if (distToPupil <= pupilR) {
                                if (isGlint) {
                                    // Pixel glint reflection
                                    r = 255; g = 255; b = 255;
                                } else {
                                    // Dark pupil center
                                    r = 5; g = 5; b = 15;
                                }
                            } else {
                                // Polar Vortex Kaleidoscope Iris
                                let angle = Math.atan2(dy, mirrorDx) + Math.PI;
                                let sector = angle % sectorAngle;
                                let foldedAngle = Math.abs(sector - sectorAngle * 0.5);

                                let twistedAngle = foldedAngle + distToPupil * twistDepth - t * 0.8;

                                let u = distToPupil * Math.cos(twistedAngle);
                                let v = distToPupil * Math.sin(twistedAngle);

                                let tileSize = 8.0;
                                let tileX = Math.floor(u / tileSize);
                                let tileY = Math.floor(v / tileSize);
                                let localU = u - tileX * tileSize - tileSize * 0.5;
                                let localV = v - tileY * tileSize - tileSize * 0.5;
                                let localDist = Math.sqrt(localU * localU + localV * localV);

                                let wave = Math.sin(localDist * 0.65 - t * 2.0 + (tileX + tileY) * 0.5);
                                let intensity = (wave + 1.0) * 0.5;

                                let pixelHue = (baseHue + distToPupil * 0.012 + intensity * 0.18) % 1.0;

                                if (intensity > 0.82) {
                                    r = 255; g = 255; b = 255;
                                } else if (intensity > 0.35) {
                                    let br = 0.5 + intensity * 0.5;
                                    r = getComponent(pixelHue, 0.95, br, 5);
                                    g = getComponent(pixelHue, 0.95, br, 3);
                                    b = getComponent(pixelHue, 0.95, br, 1);
                                } else {
                                    let darkHue = (pixelHue + 0.5) % 1.0;
                                    r = getComponent(darkHue, 1.0, 0.2, 5);
                                    g = getComponent(darkHue, 1.0, 0.2, 3);
                                    b = getComponent(darkHue, 1.0, 0.2, 1);
                                }
                            }
                        } else {
                            // Sclera (White of the eye)
                            let scleraPulse = Math.sin(x * 0.1 + y * 0.1 + t) * 15;
                            r = Math.floor(220 + scleraPulse);
                            g = Math.floor(235 + scleraPulse);
                            b = 255;
                        }
                    }
                }
            }

            // Dark void outside eye boundaries
            display.setPixel(x, y, r, g, b);
        }
    }
}
  __stack.push({
    kind: "code", opacity: 1, blend: "normal", recolor: false, role: "paint", maskInvert: false,
    lut: null,
    buf: new Uint8ClampedArray(__W * __H * 4),
    params: {},
    fSetup: typeof setup === "function" ? setup : null,
    fUpdate: typeof update === "function" ? update : null,
    fDraw: typeof draw === "function" ? draw : null,
  });
})();

// ── pixel layer: Nose ──
__stack.push({
  kind: "pixel", opacity: 1, blend: "normal", role: "paint", maskInvert: false,
  buf: __b64("", __PW * __PH * 4),
});

// Mask grouping: a mask layer paints nothing — it gates the nearest paint
// layer BELOW it (stacked masks intersect). Binary threshold: pixel-art masks
// switch on where alpha >= 0.5, code masks where luminance × alpha >= 0.5.
const __groups = [];
{
  let last = null;
  for (const L of __stack) {
    if (L.role === "mask") { if (last) last.masks.push(L); continue; }
    L.masks = [];
    last = L;
    if (L.opacity > 0) __groups.push(L);
  }
}

// Pixel-art layers keep their authored size and sit centred on the 128x128
// panel; code layers render at the full panel size.
function __pix(i) {
  const x = (i % __W) - __OX, y = ((i / __W) | 0) - __OY;
  return x < 0 || x >= __PW || y < 0 || y >= __PH ? -1 : (y * __PW + x) * 4;
}

function __maskOn(M, j) {
  const B = M.buf;
  let on;
  if (M.kind === "pixel") on = B[j + 3] >= 128;
  else on = (0.2126 * B[j] + 0.7152 * B[j + 1] + 0.0722 * B[j + 2]) * (B[j + 3] / 255) >= 127.5;
  return M.maskInvert ? !on : on;
}

// One shared knob set: every layer receives the same input, exactly like
// patterns running on the device's four physical encoders.
function __mirror(L) {
  const inp = L.lastInput;
  if (!inp) return;
  L.params.knobValues = inp.knobValues;
  L.params.knobNormalized = inp.knobNormalized;
  L.params.knobDeltas = inp.knobDeltas;
  L.params.knobRanges = inp.knobRanges;
  L.params.btnPressed = inp.btnPressed;
  L.params.btnHeld = inp.btnHeld;
}

export function setup(params) {
  for (const L of __stack) {
    if (L.kind !== "code") continue;
    L.display = __mkDisplay(L);
    if (L.fSetup) L.fSetup(L.params);
  }
}

export function update(dt, input, params) {
  for (const L of __stack) {
    if (L.kind !== "code") continue;
    L.lastInput = input;
    __mirror(L);
    if (L.fUpdate) L.fUpdate(dt, input, L.params);
  }
}

export function draw(display, params, time) {
  for (const L of __stack) {
    if (L.kind !== "code" || !L.fDraw) continue;
    L.buf.fill(0);
    __mirror(L);
    L.fDraw(L.display, L.params, time);
    if (L.recolor && L.lut) {
      const B = L.buf, T = L.lut;
      for (let i = 0; i < B.length; i += 4) {
        if (B[i + 3] === 0) continue;
        const lum = Math.round(0.2126 * B[i] + 0.7152 * B[i + 1] + 0.0722 * B[i + 2]) * 4;
        B[i] = T[lum]; B[i + 1] = T[lum + 1]; B[i + 2] = T[lum + 2]; B[i + 3] = T[lum + 3];
      }
    }
  }

  // Composite bottom → top over the panel's opaque black.
  const count = __W * __H;
  for (let i = 0; i < count; i++) {
    const j = i * 4;
    let r = 0, g = 0, b = 0;
    for (const L of __groups) {
      let hidden = false;
      for (let m = 0; m < L.masks.length; m++) {
        if (!__maskOn(L.masks[m], j)) { hidden = true; break; }
      }
      if (hidden) continue;
      const B = L.buf, k = L.kind === "pixel" ? __pix(i) : j;
      if (k < 0) continue;
      const a = (B[k + 3] / 255) * L.opacity;
      if (a <= 0) continue;
      const sr = B[k], sg = B[k + 1], sb = B[k + 2], inv = 1 - a;
      if (L.blend === "add") { r += sr * a; g += sg * a; b += sb * a; }
      else if (L.blend === "multiply") {
        r = r * inv + ((r * sr) / 255) * a;
        g = g * inv + ((g * sg) / 255) * a;
        b = b * inv + ((b * sb) / 255) * a;
      } else if (L.blend === "screen") {
        r = r * inv + (255 - ((255 - r) * (255 - sr)) / 255) * a;
        g = g * inv + (255 - ((255 - g) * (255 - sg)) / 255) * a;
        b = b * inv + (255 - ((255 - b) * (255 - sb)) / 255) * a;
      } else {
        r = r * inv + sr * a;
        g = g * inv + sg * a;
        b = b * inv + sb * a;
      }
    }
    display.setPixel(i % __W, (i / __W) | 0, r, g, b);
  }
}

